 /** Whether one rule applies to a request. See README.md. */
 export function matches(rule: Rule, request: AccessRequest): boolean {
-  throw new Error("not implemented");
+  const roleMatches = rule.role === "*" || request.roles.includes(rule.role);
+  const actionMatches = rule.action === "*" || rule.action === request.action;
+  const resourceMatches =
+    rule.resource === "*" ||
+    (rule.resource.endsWith("/*")
+      ? request.resource.startsWith(rule.resource.slice(0, -1))
+      : rule.resource === request.resource);
+  return roleMatches && actionMatches && resourceMatches;
+}
+
+/** Decide a request and say which rule decided it. */
+export function explain(rules: Rule[], request: AccessRequest): Decision {
+  let decided: Rule | undefined;
+  for (const rule of rules) {
+    if (matches(rule, request)) decided = rule;
+  }
+  return { allowed: decided !== undefined && decided.effect === "allow", rule: decided };
 }

